void opeu_notice_begin(uint8_t ds[65536], HostEvent event, uint16_t sp) {
  ATTACK();
  COLLECT();
  SET_PRESENTATION(VIEW_BATTLE());
  DECIDE();
  RECORDS_BUILD();
}

